import{_ as o,o as t,c as i,a0 as a}from"./chunks/framework.ChlVJx0I.js";const w=JSON.parse('{"title":"Context window cap via provider re-registration","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-context-window-cap-via-provider-reregistration.md","filePath":"adr/0004-context-window-cap-via-provider-reregistration.md","lastUpdated":1790503232000}'),r={name:"adr/0004-context-window-cap-via-provider-reregistration.md"};function s(n,e,d,c,p,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="context-window-cap-via-provider-re-registration" tabindex="-1">Context window cap via provider re-registration <a class="header-anchor" href="#context-window-cap-via-provider-re-registration" aria-label="Permalink to &quot;Context window cap via provider re-registration&quot;">​</a></h1><p>Amended by <a href="/pi-extensions/adr/0027-the-live-catalog-comparison-heals-the-window.html">ADR 0027</a> for live-catalog providers: the re-registration is skipped for a provider that re-fetches its model list from the server (it exposes <code>refreshModels</code>), because the composer replaces the live list with the static one and the window stops moving in either direction. For those providers the cap is enforced by clamping the session&#39;s model in place at every boundary the window is consumed. The cap extension also publishes the cap it resolves in session_start to the shared record in extensions/shared/context-window-cap.ts, so the llama refresh compare can clamp both sides of its registry-to-registry compare to the value the session actually holds: a cap that hides a drift (the live window stays above the cap) then moves nothing and says nothing instead of re-applying a window the cap clamps back. The rest stands.</p><p>The <code>context-cap</code> extension limits a session&#39;s effective context window so auto-compaction fires early. pi has no cap concept; the only source of truth is <code>model.contextWindow</code> on the model object the session resolves. We apply the cap by re-registering each provider&#39;s model list (with capped <code>contextWindow</code>) through the extension <code>registerProvider</code> API, instead of hooking <code>session_start</code>/<code>model_select</code> and calling <code>setModel</code> with a capped copy.</p><p>The hook path was rejected because <code>setModel</code> appends a <code>model_change</code> entry to the session transcript on every call (polluting every session start and switch) and because the <code>/model</code> picker would keep showing the true window while compaction acted on the capped one. The registry path makes the capped window the value pi resolves everywhere: initial model, resume, model switches, picker, footer. The composer keeps base auth, streaming, and model refresh for re-registered providers, so no provider behavior changes except the window.</p><p>Cost accepted: the extension copies every model field at load and must keep that copy complete when pi&#39;s model shape grows.</p>',5)])])}const m=o(r,[["render",s]]);export{w as __pageData,m as default};
